import json,subprocess,tempfile,os
runs=json.load(open('generation-media.json'))['runs']
for i,r in enumerate(runs,1):
 with tempfile.TemporaryDirectory(dir='.') as d:
  dest=os.path.join(d,'decoded.png')
  p=subprocess.run(['sips','-s','format','png',r['images'][0]['file_path'],'--out',dest],capture_output=True,text=True)
  if p.returncode or not os.path.isfile(dest) or os.path.getsize(dest)==0: raise RuntimeError(f'{i}: {p.stderr} {p.stdout}')
 print(f'{i:02}: PNG 解码成功')
PY","timeoutMs":120000}

